const input = $input.first().json.body || $input.first().json;
const dispute = input.dispute || input;
const allowed = ['QUALITY', 'QUANTITY', 'WRONG_ITEM', 'DELAYED', 'NOT_RECEIVED'];
const category = String(dispute.category || '').toUpperCase();
if (!allowed.includes(category)) throw new Error(`category must be one of ${allowed.join(', ')}`);
const evidence = { orderId: String(dispute.orderId || ''), category, description: String(dispute.description || '').slice(0, 3000), status: dispute.status || 'OPEN', escrowProtected: Boolean(dispute.escrowProtected), order: input.order ? { dealTitle: input.order.dealTitle || input.order.title || null, quantity: input.order.quantity ?? null, orderedAt: input.order.orderedAt || null, fulfillment: input.order.fulfillment || null, pickupPoint: input.order.pickupPoint || null, status: input.order.status || null } : null, vendorResponse: String(input.vendorResponse || '').slice(0, 2000), evidenceProvided: Array.isArray(input.evidenceProvided) ? input.evidenceProvided.slice(0, 12) : [] };
if (!evidence.orderId) throw new Error('orderId is required');
const checklist = { QUALITY: ['Photos of item condition and packaging', 'Deal description or agreed quality specification', 'Vendor response'], QUANTITY: ['Quantity ordered and received', 'Photos or handover count', 'Pickup or delivery record'], WRONG_ITEM: ['Item received compared with deal listing', 'Photos of labels or packaging', 'Vendor response'], DELAYED: ['Promised delivery or pickup date', 'Latest fulfillment status', 'Any notice of delay'], NOT_RECEIVED: ['Pickup or delivery confirmation', 'Collector authorization if applicable', 'Vendor handover record'] }[category];
const prompt = `You are a neutral community commerce dispute intake assistant. Summarize claims from both sides without deciding who is right. Never authorize a refund, chargeback, escrow release, payment hold, account penalty or order status change. Flag missing evidence and recommend a human reviewer. Avoid including sensitive personal data in your response.
Case evidence: ${JSON.stringify(evidence)}
Suggested evidence checklist: ${JSON.stringify(checklist)}
Return JSON {"triagePriority":"LOW|NORMAL|HIGH","neutralSummary":"...","claimantPosition":"...","vendorPosition":"...","evidenceGaps":["..."],"suggestedNextSteps":["..."],"humanDecisionRequired":true,"paymentAction":"NONE_PENDING_HUMAN_REVIEW"}.`;
return [{ json: { evidence, checklist, prompt } }];

const response = $input.first().json;
const source = $('Prepare Neutral Case Summary').first().json;
let triage;
try { triage = JSON.parse(response.candidates?.[0]?.content?.parts?.[0]?.text || '{}'); } catch { triage = null; }
if (!triage || !triage.neutralSummary) triage = { triagePriority: source.evidence.escrowProtected ? 'HIGH' : 'NORMAL', neutralSummary: 'AI summary unavailable. A human reviewer should inspect the submitted case.', claimantPosition: source.evidence.description || 'Not provided', vendorPosition: source.evidence.vendorResponse || 'No vendor response supplied', evidenceGaps: source.checklist, suggestedNextSteps: ['Collect the listed evidence from both parties.', 'Keep any payment decision pending human review.'], humanDecisionRequired: true, paymentAction: 'NONE_PENDING_HUMAN_REVIEW' };
triage.humanDecisionRequired = true; triage.paymentAction = 'NONE_PENDING_HUMAN_REVIEW';
return [{ json: { status: 'success', orderId: source.evidence.orderId, triagedAt: new Date().toISOString(), evidence: source.evidence, triage } }];
